import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:provider/provider.dart';import '../models/genre.dart';import '../models/publisher.dart';import '../models/reader.dart';import '../repositories/genre_repository.dart';import '../repositories/publisher_repository.dart';import '../repositories/reader_repository.dart';
class ReferenceDetailScreen extends StatelessWidget{final String type;final int id;const ReferenceDetailScreen({super.key,required this.type,required this.id});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('Карточка: $type')),body:FutureBuilder<Object?>(future:_load(c),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.data==null)return const Center(child:Text('Запись не найдена'));final rows=_rows(s.data!);return Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:650),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(rows.first.$2,style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:16),...rows.skip(1).map((r)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(children:[SizedBox(width:180,child:Text('${r.$1}:',style:const TextStyle(fontWeight:FontWeight.w600))),Expanded(child:Text(r.$2))]))),const SizedBox(height:18),FilledButton.icon(onPressed:()=>c.pop(),icon:const Icon(Icons.arrow_back),label:const Text('Назад'))])))));}));Future<Object?>_load(BuildContext c)=>switch(type){'жанр'=>c.read<GenreRepository>().findById(id),'издательство'=>c.read<PublisherRepository>().findById(id),_=>c.read<ReaderRepository>().findById(id)};List<(String,String)>_rows(Object e){if(e is Genre)return [('Название',e.name),('ID','${e.id}'),('Описание',e.description),('Статус',e.isDeleted?'Удалён':'Активен')];if(e is Publisher)return [('Название',e.name),('ID','${e.id}'),('Страна',e.country),('Статус',e.isDeleted?'Удалено':'Активно')];final r=e as Reader;return [('Читатель',r.fullName),('ID','${r.id}'),('E-mail',r.email),('Телефон',r.phone),('Номер билета',r.card.number),('Выдан',r.card.issuedAt.toIso8601String().split('T').first),('Действует до',r.card.expiresAt.toIso8601String().split('T').first),('Статус',r.isDeleted?'Удалён':'Активен')];}}
